<?php require dirname(__DIR__).'/app/bootstrap.php';require_admin();$error='';$edit=(int)($_GET['id']??0);
function upload_image(string $field,string $fallback): string {return cloud_upload($field,$fallback);}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$id=(int)($_POST['id']??0);$old=$id?query('SELECT * FROM products WHERE id=?',[$id])->fetch():null;if($id&&!$old)throw new DomainException('Product not found.');if(($_POST['action']??'')==='visibility'){
if(!$old)throw new DomainException('Product not found.');
$visible=($_POST['visible']??'')==='1'?1:0;
query('UPDATE products SET active=? WHERE id=?',[$visible,$id]);
if(str_contains($_SERVER['HTTP_ACCEPT']??'','application/json')){header('Content-Type: application/json');echo json_encode(['ok'=>true,'visible'=>(bool)$visible]);exit;}
flash($visible?'Product visible in shop.':'Product hidden from shop.');redirect('admin/products.php'.($edit?'?id='.$edit:''));
}
if(in_array($_POST['action']??'', ['archive','restore'],true)){
if(!$old)throw new DomainException('Product not found.');
$active=$_POST['action']==='restore'?1:0;query('UPDATE products SET active=? WHERE id=?',[$active,$id]);flash($active?'Product restored.':'Product archived. Order history is preserved.');redirect('admin/products.php?id='.$id);
}
$sku=trim((string)($_POST['sku']??$old['sku']??''));if(strlen($sku)>80)throw new DomainException('SKU must be at most 80 characters.');if($sku!==''&&query('SELECT id FROM products WHERE sku=? AND id<>?',[$sku,$id])->fetch())throw new DomainException('That SKU is already used.');
$name=trim((string)($_POST['name']??''));$slug=trim((string)($_POST['slug']??''));$desc=trim((string)($_POST['description']??''));$price=(string)($_POST['price']??'');$selected=array_values(array_intersect(sizes(),$_POST['sizes']??[]));if(strlen($name)<2||strlen($name)>140||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)||strlen($slug)>120||!ctype_digit($price)||(int)$price<1||(int)$price>1000000||!$selected||strlen($desc)>5000)throw new DomainException('Provide a name, unique URL slug, whole BDT price, description and at least one size.');if(query('SELECT id FROM products WHERE slug=? AND id<>?',[$slug,$id])->fetch())throw new DomainException('That URL slug already exists.');$stocks=[];foreach($selected as $s){$v=trim((string)($_POST['stock'][$s]??''));if($v!==''&&(!ctype_digit($v)||(int)$v>100000))throw new DomainException('Stock must be blank or a whole number from 0 to 100000.');$stocks[$s]=$v===''?null:(int)$v;}
$category=trim((string)($_POST['category']??''));if($category===''||strlen($category)>100)throw new DomainException('Enter a category of up to 100 characters.');if(strcasecmp($category,'Cargo Pants')===0)$category='Lowers';if(strcasecmp($category,'T-Shirts')===0)$category='T-shirts';if(array_sum(array_map(fn($f)=>(int)($f['size']??0),$_FILES))>3*1024*1024)throw new DomainException('Keep the combined photo upload under 3 MB.');$gallery=$old?product_gallery($old):[];
if(isset($_POST['gallery_present'])){
$requested=$_POST['gallery_order']??[];if(!is_array($requested)||array_diff($requested,$gallery))throw new DomainException('Invalid photo selection. Reload the editor.');
$gallery=array_values(array_unique($requested));
}
$image=upload_image('image','');$back=upload_image('back_image','');
if($image)array_unshift($gallery,$image);
if($back)array_splice($gallery,min(1,count($gallery)),0,[$back]);
for($n=0;$n<4;$n++){$extra=upload_image('extra_'.$n,'');if($extra)$gallery[]=$extra;}
$gallery=array_values(array_unique($gallery));if(!$gallery)throw new DomainException('Keep or upload at least one product photo.');if(count($gallery)>20)throw new DomainException('Use at most 20 photos per product.');
$image=$gallery[0];$back=$gallery[1]??null;
$guide=trim((string)($_POST['size_guide']??''));if(strlen($guide)>4000)throw new DomainException('Size guide must be at most 4000 characters.');
$facts=[];foreach(['fabric','fit','care'] as $field){if(isset($_POST[$field])){$facts[$field]=trim((string)$_POST[$field]);if(mb_strlen($facts[$field])>2000)throw new DomainException('Product details must be under 2000 characters each.');}}
db()->beginTransaction();
if($id){query('SELECT id FROM products WHERE id=? FOR UPDATE',[$id]);query('UPDATE products SET slug=?,name=?,description=?,price=?,image=?,back_image=?,active=? WHERE id=?',[$slug,$name,$desc,(int)$price,$image,$back?:null,isset($_POST['active'])?1:0,$id]);}else{query('INSERT INTO products(slug,name,description,price,image,back_image,active) VALUES(?,?,?,?,?,?,?)',[$slug,$name,$desc,(int)$price,$image,$back?:null,isset($_POST['active'])?1:0]);$id=(int)db()->lastInsertId();}
query('UPDATE products SET category=?,sku=?,source_images=? WHERE id=?',[$category,$sku?:null,json_encode($gallery),$id]);
if(isset($_POST['size_guide']))query('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',['size_guide_'.$id,$guide]);
foreach($facts as $field=>$value){if($value==='')query('DELETE FROM settings WHERE name=?',[$field.'_'.$id]);else query('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$field.'_'.$id,$value]);}
// Preserve variants referenced by pending reservations; removed sizes are disabled with zero stock.
foreach(sizes() as $s){if(in_array($s,$selected,true))query('INSERT INTO variants(product_id,size,stock) VALUES(?,?,?) ON DUPLICATE KEY UPDATE stock=VALUES(stock)',[$id,$s,$stocks[$s]]);else query('UPDATE variants SET stock=0 WHERE product_id=? AND size=?',[$id,$s]);}db()->commit();flash('Product saved.');redirect('admin/products.php?id='.$id);
}catch(DomainException $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
$p=$edit?query('SELECT * FROM products WHERE id=?',[$edit])->fetch():null;$variants=$p?query('SELECT * FROM variants WHERE product_id=?',[$edit])->fetchAll():[];$stocks=array_column($variants,'stock','size');$products=query('SELECT * FROM products ORDER BY id DESC')->fetchAll();render_header('Products',true); ?>
<main class="page"><div class="section-head"><div><p class="eyebrow">YOUR GROWING COLLECTION</p><h1>Products.</h1></div><a class="button outline" href="<?=url('admin/products.php')?>">+ NEW PRODUCT</a></div><div class="checkout-layout"><section><h2><?=$p?'Edit product':'Add a product'?></h2><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif ?><form method="post" enctype="multipart/form-data"><?=csrf_input()?><input type="hidden" name="id" value="<?=h($p['id']??0)?>"><label>Product name<input name="name" maxlength="140" value="<?=h($p['name']??'')?>" required></label><label>URL slug<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="120" placeholder="living-tee" value="<?=h($p['slug']??'')?>" required></label><label>SKU / product code<input name="sku" maxlength="80" value="<?=h($p['sku']??'')?>" placeholder="Unique product code"></label><label>Price in BDT<input type="number" name="price" min="1" max="1000000" step="1" value="<?=h($p['price']??'')?>" required></label><label>Category<input name="category" list="product-categories" maxlength="100" value="<?=h($p['category']??'')?>" placeholder="Choose or type a category" required></label><datalist id="product-categories"><?php foreach(array_unique(array_merge(['T-shirts','Hoodies','Lowers'],array_filter(array_column($products,'category')))) as $category):?><option value="<?=h($category)?>"><?php endforeach ?></datalist><label>Description<textarea name="description" maxlength="5000"><?=h($p['description']??'')?></textarea></label><?php foreach(['fabric'=>'Fabric / composition','fit'=>'Fit notes','care'=>'Washing instructions'] as $field=>$label):?><label><?=h($label)?><textarea name="<?=$field?>" maxlength="2000"><?=h($p?setting($field.'_'.$p['id']):'')?></textarea></label><?php endforeach ?><p class="hint">Use confirmed product details. Blank fabric and fit fields use the catalogue description; blank care uses general guidance.</p><label>Size guide &amp; fit notes<textarea name="size_guide" maxlength="4000" placeholder="State units (cm or inches), then add each size's garment measurements and fit notes."><?=h($p?setting('size_guide_'.$p['id']):'')?></textarea></label><p class="hint">Enter actual measurements for this product. Leave blank until measured; no measurements will be invented.</p><h2>Product photos</h2><p class="hint">First photo is the cover. Second photo appears on hover. Move photos earlier or later to choose their order. Changes apply when you save.</p><input type="hidden" name="gallery_present" value="1"><div class="photo-editor" data-photo-editor>
<?php foreach($p?product_gallery($p):[] as $i=>$photo):?><div class="photo-tile"><img src="<?=url(h($photo))?>" alt="Product photo <?=$i+1?>" loading="lazy"><input type="hidden" name="gallery_order[]" value="<?=h($photo)?>"><strong data-photo-role><?=$i===0?'Cover':($i===1?'Hover':'Gallery')?></strong><div class="photo-actions"><button type="button" data-photo-move="-1" aria-label="Move photo earlier">← Earlier</button><button type="button" data-photo-move="1" aria-label="Move photo later">Later →</button><button type="button" data-photo-remove>Remove</button></div></div><?php endforeach ?></div>
<div class="form-grid"><label>Upload new cover<input type="file" name="image" accept="image/png,image/jpeg,image/webp" <?=$p?'':'required'?>></label><label>Upload new hover photo<input type="file" name="back_image" accept="image/png,image/jpeg,image/webp"></label><?php for($n=0;$n<4;$n++):?><label>Additional photo <?=$n+1?><input type="file" name="extra_<?=$n?>" accept="image/png,image/jpeg,image/webp"></label><?php endfor ?></div><p class="hint">PNG, JPEG or WebP. Photos are automatically compressed before upload. Maximum 3 MB combined after compression per save; 20 photos per product. New cover and hover uploads move to the front; existing photos remain until removed.</p><h2>Sizes & inventory</h2><p class="hint">Blank stock means inventory is not tracked. Use 0 for sold out. Enter the currently available quantity after existing orders have been reserved.</p><div class="inventory-grid"><?php foreach(sizes() as $s):?><div><label class="check-label"><input type="checkbox" name="sizes[]" value="<?=$s?>" <?=array_key_exists($s,$stocks)?'checked':''?>><?=$s?></label><input aria-label="<?=$s?> stock" type="number" min="0" max="100000" name="stock[<?=$s?>]" value="<?=h($stocks[$s]??'')?>" placeholder="Untracked"></div><?php endforeach ?></div><label class="check-label"><input type="checkbox" name="active" value="1" <?=!$p||$p['active']?'checked':''?>>Visible in shop</label><button class="button dark">SAVE PRODUCT ↗</button></form><?php if($p):?><div class="product-controls"><a href="<?=url('product.php?slug='.rawurlencode($p['slug']))?>" target="_blank" rel="noopener">View product ↗</a><form method="post"><?=csrf_input()?><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="action" value="<?=$p['active']?'archive':'restore'?>"><p class="hint">Archive removes the listing from the shop, preserves past orders, and can be restored here.</p><button class="button outline"><?=$p['active']?'ARCHIVE / DELETE FROM SHOP':'RESTORE PRODUCT'?></button></form></div><?php endif ?></section><aside><h2>All products</h2><label>Search products<input type="search" data-product-search placeholder="Name, SKU or category"></label><label>Status<select data-product-filter><option value="all">All products</option><option value="visible">Visible</option><option value="hidden">Hidden / archived</option></select></label><div data-product-list><?php foreach($products as $item):?><div class="bag-row product-list-row" data-status="<?=$item['active']?'visible':'hidden'?>"><a class="product-list-link" href="<?=url('admin/products.php?id='.$item['id'])?>"><img src="<?=url(h(product_photo($item['image'],240)))?>" alt="" loading="lazy"><div><h3><?=h($item['name'])?></h3><p><?=money($item['price'])?> · <span data-product-visibility><?=$item['active']?'Visible':'Hidden / archived'?></span></p><p><?=h($item['sku']??'')?> · <?=h($item['category'])?></p></div></a><form method="post" data-visibility-form><?=csrf_input()?><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="action" value="visibility"><label class="check-label"><input type="checkbox" name="visible" value="1" <?=$item['active']?'checked':''?> aria-label="Visible in shop: <?=h($item['name'])?>">Visible</label><button type="submit" class="text-button">SAVE VISIBILITY</button><small role="status" data-visibility-status></small></form></div><?php endforeach ?></div></aside></div></main><?php render_footer(); ?>
